action.command:
cd /workspace && cat > /tmp/srv.mjs <<'EOF'
import http from 'http';
import fs from 'fs';
import path from 'path';
const root = '/workspace/dist';
const types = {'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.gif':'image/gif','.woff':'font/woff','.woff2':'font/woff2'};
http.createServer((req,res)=>{
  let p = decodeURIComponent(req.url.split('?')[0]);
  if(p.endsWith('/')) p+='index.html';
  const f = path.join(root,p);
  if(!f.startsWith(root) || !fs.existsSync(f) || fs.statSync(f).isDirectory()){res.writeHead(404);res.end('nf');return;}
  res.writeHead(200,{'Content-Type':types[path.extname(f)]||'application/octet-stream'});
  fs.createReadStream(f).pipe(res);
}).listen(8099,()=>console.log('up'));
EOF
nohup node /tmp/srv.mjs >/tmp/srv.log 2>&1 & sleep 2; cat /tmp/srv.log; for u in basic/index.html "mastercode/3_26_1_410dc25_git_last_commit_at_2026-09-23__10-05-39/js/masterportal.js" "mastercode/3_26_1_410dc25_git_last_commit_at_2026-09-23__10-05-39/css/masterportal.css" basic/config.js basic/config.json basic/resources/services.json basic/resources/style_v3.json basic/resources/rest-services.json; do printf "%s -> " "$u"; curl -s -o /dev/null -w "%{http_code} %{size_download}\n" "http://127.0.0.1:8099/$u"; done

